<?php
/**
 * Listing engine: every listing has the common fields (A–G) plus the fields of its
 * category, all described in data/listing-schema.json (generated by
 * backend/scripts/build-listing-schema.py). The same file drives the supplier
 * wizard in the app, the wp-admin editor and the completeness check.
 *
 * Values are post meta named after the field key:
 *   text/textarea/select/number → string, multiselect → "a, b", list → one per line,
 *   boolean → "1" or "", rows → JSON, itinerary → see itinerary.php.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function tac_listing_schema() {
	static $schema = null;
	if ( null === $schema ) {
		$schema = json_decode( (string) file_get_contents( TAC_DIR . 'data/listing-schema.json' ), true ); // phpcs:ignore WordPress.WP.AlternativeFunctions
		if ( ! is_array( $schema ) ) {
			$schema = array( 'categories' => array(), 'common' => array(), 'listingTypes' => array() );
		}
	}
	return $schema;
}

/**
 * @return array|null The category definition (slug, name, listingType, subtypes, sections).
 */
function tac_listing_category( $slug ) {
	foreach ( tac_listing_schema()['categories'] as $cat ) {
		if ( $cat['slug'] === $slug ) {
			return $cat;
		}
	}
	return null;
}

function tac_listing_type_def( $key ) {
	foreach ( tac_listing_schema()['listingTypes'] as $type ) {
		if ( $type['key'] === $key ) {
			return $type;
		}
	}
	return null;
}

/**
 * Sections for a category: the common ones, then the category's own. A category field
 * replaces the common field with the same key.
 *
 * @return array[] Sections with 'title', 'fields', and 'group' ('common' or 'category').
 */
function tac_listing_sections( $category_slug ) {
	$cat      = tac_listing_category( $category_slug );
	$own      = $cat ? $cat['sections'] : array();
	$own_keys = array();
	foreach ( $own as $sec ) {
		foreach ( $sec['fields'] as $field ) {
			$own_keys[ $field['key'] ] = true;
		}
	}
	$sections = array();
	foreach ( tac_listing_schema()['common'] as $sec ) {
		$sec['fields'] = array_values(
			array_filter(
				$sec['fields'],
				function ( $field ) use ( $own_keys ) {
					return ! isset( $own_keys[ $field['key'] ] );
				}
			)
		);
		$sec['group']  = 'common';
		$sections[]    = $sec;
	}
	foreach ( $own as $sec ) {
		$sec['group'] = 'category';
		$sections[]   = $sec;
	}
	return $sections;
}

/**
 * @return array<string, array> Field definitions by key for a category.
 */
function tac_listing_fields( $category_slug ) {
	$fields = array();
	foreach ( tac_listing_sections( $category_slug ) as $sec ) {
		foreach ( $sec['fields'] as $field ) {
			$fields[ $field['key'] ] = $field;
		}
	}
	return $fields;
}

/** All field definitions across categories (a key's first definition wins). */
function tac_listing_all_fields() {
	static $all = null;
	if ( null === $all ) {
		$all    = array();
		$schema = tac_listing_schema();
		$secs   = $schema['common'];
		foreach ( $schema['categories'] as $cat ) {
			$secs = array_merge( $secs, $cat['sections'] );
		}
		foreach ( $secs as $sec ) {
			foreach ( $sec['fields'] as $field ) {
				$all[ $field['key'] ] = $all[ $field['key'] ] ?? $field;
			}
		}
	}
	return $all;
}

/* ---------- Reading ---------- */

/**
 * A field's stored value. The short summary is the post excerpt; everything else is post meta.
 */
function tac_listing_raw( $post_id, $key ) {
	return 'excerpt' === $key ? (string) get_post_field( 'post_excerpt', $post_id ) : get_post_meta( $post_id, $key, true );
}

/**
 * A stored value in its natural shape: arrays for lists, multiselects and rows.
 */
function tac_listing_decode( array $field, $raw ) {
	switch ( $field['type'] ) {
		case 'list':
			return tac_lines( $raw );
		case 'multiselect':
			return array_values( array_filter( array_map( 'trim', explode( ',', (string) $raw ) ), 'strlen' ) );
		case 'rows':
			$rows = json_decode( (string) $raw, true );
			return is_array( $rows ) ? array_values( array_filter( $rows, 'is_array' ) ) : array();
		case 'boolean':
			return (bool) $raw;
		case 'number':
			return '' === (string) $raw || null === $raw ? null : (float) $raw;
		default:
			return (string) $raw;
	}
}

/**
 * Values of every field of the listing's category (itinerary excluded: see tac_get_itinerary()).
 */
function tac_listing_values( $post_id ) {
	$values = array();
	foreach ( tac_listing_fields( tac_listing_category_of( $post_id ) ) as $key => $field ) {
		if ( 'itinerary' === $field['type'] ) {
			continue;
		}
		$values[ $key ] = tac_listing_decode( $field, tac_listing_raw( $post_id, $key ) );
	}
	return $values;
}

function tac_listing_category_of( $post_id ) {
	$slug = (string) get_post_meta( $post_id, 'listing_category', true );
	return tac_listing_category( $slug ) ? $slug : '';
}

/* ---------- Saving ---------- */

/**
 * Clean one submitted value for storage.
 */
function tac_listing_sanitize( array $field, $value ) {
	$allowed = isset( $field['options'] ) ? wp_list_pluck( $field['options'], 'value' ) : null;
	switch ( $field['type'] ) {
		case 'boolean':
			return ! empty( $value ) && 'false' !== $value ? '1' : '';
		case 'number':
			return is_numeric( $value ) ? (string) max( 0, (float) $value ) : '';
		case 'select':
			$value = sanitize_text_field( (string) $value );
			return null === $allowed || in_array( $value, $allowed, true ) ? $value : '';
		case 'multiselect':
			$items = is_array( $value ) ? $value : explode( ',', (string) $value );
			$items = array_map( 'sanitize_text_field', array_map( 'trim', $items ) );
			$items = array_values( array_filter( $items, fn( $v ) => '' !== $v && ( null === $allowed || in_array( $v, $allowed, true ) ) ) );
			return implode( ', ', array_unique( $items ) );
		case 'list':
			$items = is_array( $value ) ? $value : preg_split( '/\r\n|\r|\n/', (string) $value );
			return implode( "\n", array_filter( array_map( 'sanitize_text_field', array_map( 'trim', $items ) ), 'strlen' ) );
		case 'rows':
			$rows  = is_array( $value ) ? $value : json_decode( (string) $value, true );
			$clean = array();
			foreach ( is_array( $rows ) ? $rows : array() as $row ) {
				if ( ! is_array( $row ) ) {
					continue;
				}
				$out = array();
				foreach ( $field['columns'] as $col ) {
					$v                   = $row[ $col['key'] ] ?? '';
					$out[ $col['key'] ] = 'number' === $col['type'] ? ( is_numeric( $v ) ? (float) $v : null ) : sanitize_text_field( (string) $v );
				}
				if ( array_filter( $out, fn( $v ) => null !== $v && '' !== $v ) ) {
					$clean[] = $out;
				}
			}
			return wp_json_encode( $clean );
		case 'textarea':
			return sanitize_textarea_field( (string) $value );
		default:
			return sanitize_text_field( (string) $value );
	}
}

/**
 * Save the submitted values of the listing's fields. Keys not in $input are left unchanged.
 */
function tac_listing_save( $post_id, $category_slug, array $input ) {
	$fields   = tac_listing_fields( $category_slug );
	$excerpts = array();
	foreach ( $input as $key => $value ) {
		if ( ! isset( $fields[ $key ] ) ) {
			continue;
		}
		if ( 'itinerary' === $fields[ $key ]['type'] ) {
			tac_set_itinerary( $post_id, is_array( $value ) ? $value : array() );
			continue;
		}
		$clean = tac_listing_sanitize( $fields[ $key ], $value );
		if ( 'excerpt' === $key ) {
			$excerpts[] = $clean;
			continue;
		}
		update_post_meta( $post_id, $key, wp_slash( $clean ) );
	}
	if ( ! empty( $excerpts ) && ! wp_is_post_revision( $post_id ) ) {
		// Avoid re-running save_post handlers for this update.
		global $wpdb;
		$wpdb->update( $wpdb->posts, array( 'post_excerpt' => mb_substr( end( $excerpts ), 0, 300 ) ), array( 'ID' => $post_id ) ); // phpcs:ignore WordPress.DB.DirectDatabaseQuery
		clean_post_cache( $post_id );
	}
	tac_listing_sync( $post_id );
}

/**
 * Category, subtype and the values other parts of the site read (free cancellation,
 * start city, browse categories) after any save.
 */
function tac_listing_sync( $post_id ) {
	$category = tac_listing_category_of( $post_id );
	$policy   = (string) get_post_meta( $post_id, 'cancellation_policy', true );
	if ( '' !== $policy ) {
		update_post_meta( $post_id, 'free_cancel', 0 === strpos( $policy, 'free_' ) ? 1 : 0 );
	}
	if ( ! get_post_meta( $post_id, 'start_point', true ) && get_post_meta( $post_id, 'city', true ) ) {
		$city = tac_listing_option_label( 'city', (string) get_post_meta( $post_id, 'city', true ) );
		if ( 'Other' !== $city ) {
			update_post_meta( $post_id, 'start_point', $city );
		}
	}
	if ( $category ) {
		tac_listing_assign_terms( $post_id, $category, (string) get_post_meta( $post_id, 'listing_subtype', true ) );
	}
}

/**
 * Browse categories: the category, its subtype and, for multi-day tours,
 * "Morocco Tours From <start city>" when that term exists.
 */
function tac_listing_assign_terms( $post_id, $category, $subtype ) {
	$slugs = array( $category );
	if ( $subtype ) {
		$slugs[] = $subtype;
	}
	if ( 'tour-packages' === $category ) {
		$start = sanitize_title( (string) get_post_meta( $post_id, 'start_point', true ) );
		if ( $start && term_exists( 'tours-from-' . $start, 'tour_category' ) ) {
			$slugs[] = 'tours-from-' . $start;
		}
	}
	$ids = array();
	foreach ( $slugs as $slug ) {
		$term = get_term_by( 'slug', $slug, 'tour_category' );
		if ( $term ) {
			$ids[] = (int) $term->term_id;
		}
	}
	if ( $ids ) {
		wp_set_object_terms( $post_id, $ids, 'tour_category' );
	}
}

function tac_listing_option_label( $key, $value ) {
	$field = tac_listing_all_fields()[ $key ] ?? null;
	foreach ( $field['options'] ?? array() as $opt ) {
		if ( $opt['value'] === $value ) {
			return $opt['label'];
		}
	}
	return $value;
}

/* ---------- Completeness ---------- */

function tac_listing_field_visible( array $field, $get ) {
	if ( empty( $field['show_if'] ) ) {
		return true;
	}
	$cond  = $field['show_if'];
	$value = (string) $get( $cond['field'] );
	if ( isset( $cond['in'] ) ) {
		return in_array( $value, $cond['in'], true );
	}
	return ! in_array( $value, $cond['not_in'] ?? array(), true );
}

/**
 * Required information still missing before the listing can be submitted.
 *
 * @return array<int, array{key: string, label: string, step: int}>
 */
function tac_listing_missing( $post_id ) {
	$post    = get_post( $post_id );
	$missing = array();
	$cat     = tac_listing_category_of( $post_id );
	if ( ! $cat ) {
		return array( array( 'key' => 'listing_category', 'label' => __( 'Category', 'travel-agency-core' ), 'step' => 1 ) );
	}
	if ( ! $post || '' === trim( $post->post_title ) ) {
		$missing[] = array( 'key' => 'title', 'label' => __( 'Title', 'travel-agency-core' ), 'step' => 2 );
	}
	if ( ! $post || strlen( wp_strip_all_tags( $post->post_content ) ) < 80 ) {
		$missing[] = array( 'key' => 'description', 'label' => __( 'Overview (at least 80 characters)', 'travel-agency-core' ), 'step' => 2 );
	}
	if ( ! has_post_thumbnail( $post_id ) && ! get_post_meta( $post_id, 'image_url', true ) ) {
		$missing[] = array( 'key' => 'photo', 'label' => __( 'Cover photo', 'travel-agency-core' ), 'step' => 6 );
	}
	$get = fn( $key ) => tac_listing_raw( $post_id, $key );
	foreach ( tac_listing_sections( $cat ) as $sec ) {
		$step = $sec['step'] ?? 3;
		foreach ( $sec['fields'] as $field ) {
			if ( empty( $field['required'] ) || ! tac_listing_field_visible( $field, $get ) ) {
				continue;
			}
			$empty = 'itinerary' === $field['type']
				? ! tac_get_itinerary( $post_id )
				: ( 'rows' === $field['type'] ? ! tac_listing_decode( $field, $get( $field['key'] ) ) : '' === trim( (string) $get( $field['key'] ) ) );
			if ( $empty ) {
				$missing[] = array( 'key' => $field['key'], 'label' => $field['label'], 'step' => $step );
			}
		}
	}
	return $missing;
}
